BANK.push({"id": "GOV-N105", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.1AI政策與治理指引", "q": "某機關研考會議討論「ISO/IEC 42001」與「NIST AI RMF」的差異，下列敘述何者最正確？", "o": ["NIST AI RMF為具強制力的國際標準，ISO/IEC 42001則僅適用於美國聯邦機關", "兩者皆為歐盟AI法案的附屬法規，機關或企業違反時將受到歐盟裁處罰鍰", "前者為可第三方驗證的管理系統標準，後者為自願採用的風險管理框架", "ISO/IEC 42001專責評測模型準確率，NIST AI RMF則專責規範資料中心能耗"], "a": 3, "e": "ISO/IEC 42001是AI管理系統標準，組織可申請第三方驗證；NIST AI RMF則是供自願採用的風險管理框架，不提供驗證。"});
BANK.push({"id": "GOV-N106", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.1AI政策與治理指引", "q": "某機關辦理AI公文分類系統採購評選，甲廠商簡報宣稱「本系統分類準確率高達99%」。評選委員為初步辨識風險，最適當的提問或要求為何？", "o": ["請廠商說明測試條件，並以機關代表性資料實測", "數字已相當亮眼，可直接將該項列為最高分以鼓勵廠商投入研發", "要求廠商將準確率承諾提高到百分之百，並明確寫入契約條款", "改以廠商過去五年得標件數，作為判斷技術能力的唯一依據"], "a": 1, "e": "廠商自報指標可能來自與機關業務不同的資料或條件，應確認測試方法，並以機關代表性資料驗證效能。"});
BANK.push({"id": "GOV-N107", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.1AI政策與治理指引", "q": "承辦人審查AI系統委外契約草案時，發現條文寫明「系統產出內容之正確性及因而衍生之一切責任，概由機關自行負擔，廠商不負任何責任」。下列處理最適當？", "o": ["照案簽辦，因為機關本來就要對行政行為負全責，此條文不會產生影響", "刪除整份契約中所有的責任條款，以免雙方日後因條文解釋發生爭議", "提出意見，協商依可歸責程度明定雙方責任與瑕疵改正義務", "改為約定一切責任均由廠商無上限承擔，機關在任何情況下完全免責"], "a": 3, "e": "契約應合理分配責任，將廠商可控的系統瑕疵、資安與資料品質責任明定，並約定改正義務，而非全由一方承擔。"});
BANK.push({"id": "GOV-N108", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.1AI政策與治理指引", "q": "某局規劃上線AI智慧客服，回答民眾有關各項補助申請資格的問題。下列哪一組「風險辨識與控管措施」最為適當？", "o": ["回覆速度可能過慢；只要增加伺服器數量並升級網路頻寬即可解決", "民眾可能不會使用；應取消人工服務窗口，讓民眾逐漸習慣使用AI", "AI用語可能過於正式；應改用網路流行語與表情符號提高親和力", "錯誤資訊可能損及權益；限以官方最新資料回答、附出處並可轉真人"], "a": 4, "e": "補助資格資訊錯誤會直接影響民眾權益，應以權威資料為據、標示出處，並保留人工服務作為補救。"});
BANK.push({"id": "GOV-N109", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.1AI政策與治理指引", "q": "某機關同時使用同一套語言模型做兩件事：一是整理內部會議紀錄摘要，二是建議是否對違規業者裁處罰鍰。就風險分級而言，下列敘述何者最正確？", "o": ["兩者使用同一個模型，因此風險等級必然完全相同", "風險依用途與權益影響而定，裁處建議應採較嚴格控管", "會議紀錄的文字量較大，所以風險應高於裁處建議", "風險等級只取決於模型參數規模，與實際用途無關"], "a": 2, "e": "風險分級應以應用情境與對人民權益的影響判斷，同一技術用於影響裁罰的決策時風險較高。"});
BANK.push({"id": "GOV-N110", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.1AI政策與治理指引", "q": "某機關將統計資料發布於政府資料開放平臺，希望外界能合法地將其用於AI應用。依AI友善資料原則，除提供機器可讀格式外，下列何者最為重要？", "o": ["僅提供圖片檔，避免資料遭到大量不當下載與轉用", "不註明任何授權條件，讓使用者依需要自行判斷能否使用", "要求使用者每次使用前，都須親自到機關臨櫃提出書面申請", "附上明確的授權條款與權利宣告"], "a": 4, "e": "明確的授權與權利宣告讓使用者知道能否及如何再利用資料，是AI友善資料的重要要素。"});
BANK.push({"id": "GOV-N111", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.1AI政策與治理指引", "q": "承辦人將民眾申請資料的姓名改為流水編號，另將「編號與姓名對照表」存放於同一單位資料夾，再提供給AI分析團隊。關於此資料的性質，下列敘述何者最正確？", "o": ["姓名已全部替換為編號，因此已屬完全匿名，不再受任何個資規範拘束", "只要分析團隊書面承諾不會查看對照表，該資料即可視為公開資料", "流水編號屬系統自動產生的資料，因此不需要再評估任何再識別風險", "屬假名化資料，可經對照表還原，仍應視同個資保護"], "a": 4, "e": "以代碼取代識別資訊屬假名化，持有對照表即可還原，仍有再識別風險，應比照個資管理並妥善隔離對照表。"});
BANK.push({"id": "GOV-N112", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.1AI政策與治理指引", "q": "某機關以檢索增強生成（RAG）建置法規問答系統。某法規修正施行後，系統仍不時引用舊條文回答。依資料治理觀點，最根本的改善作法為何？", "o": ["建立版本控制，標示生效與廢止日期並更新知識庫", "在回答下方加註警語，請民眾自行判斷AI回答的內容是否為最新版本", "將模型更換為參數規模更大的版本，即可讓AI自動辨識新舊法規差異", "刪除知識庫中所有的歷史法規資料，日後也不再保留任何舊版本文件"], "a": 1, "e": "知識庫應實施版本控制並維護生效狀態，確保檢索時優先取得現行有效版本；舊版可另行保存供查考。"});
BANK.push({"id": "GOV-N113", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.1AI政策與治理指引", "q": "某機關希望AI問答系統的每一則回答都能附上「出自哪一份文件的哪一段」，以利民眾與同仁查證。在準備知識庫資料時，下列哪一項措施最有助於達成「可引用」？", "o": ["把所有文件合併為單一大型檔案，以減少知識庫中的檔案數量", "為文件與段落建立穩定的識別碼或連結", "移除文件中的標題、文號與日期，避免干擾模型對內容的理解", "只保留每份文件的內容摘要，並刪除原文以節省系統儲存空間"], "a": 2, "e": "可引用性仰賴穩定的識別碼、段落定位與詮釋資料，AI才能準確指出回答依據的來源。"});
BANK.push({"id": "GOV-N114", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.1AI政策與治理指引", "q": "某單位歷年統計報表都以掃描影像的PDF檔保存。若要讓AI有效讀取與分析這些數據，下列哪一種處理最符合「機器可讀」原則？", "o": ["把PDF檔全部列印成紙本，再以更高解析度重新掃描一次", "將影像PDF壓縮成更小的檔案，以便透過電子郵件傳送", "在每個檔名前加上「重要」字樣，讓AI優先讀取這些檔案", "將表格轉為CSV等結構化格式並附欄位說明"], "a": 4, "e": "機器可讀是指資料能被程式直接解析，結構化格式搭配欄位說明遠比影像檔利於AI處理。"});
BANK.push({"id": "GOV-N115", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.1AI政策與治理指引", "q": "某機關委外建置AI案件分類系統，廠商要求直接以近三年含完整個資的正式案件資料進行系統測試。下列作法何者最適當？", "o": ["正式資料最能反映真實情況，應全數提供給廠商以求測試完整", "為加快專案進度，可將資料以電子郵件直接寄給廠商人員處理", "優先用去識別化或模擬資料，必要時才在控管下限量使用真實資料", "測試資料不屬於正式上線使用，因此不需要採取任何保護措施"], "a": 3, "e": "測試階段應遵循資料最小化，優先採用去識別化或模擬資料，必要時才在控管下使用真實資料。"});
BANK.push({"id": "GOV-N116", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.1AI政策與治理指引", "q": "某局擬將他機關依業務合作提供的稽查資料，放入本局AI知識庫作為生成回答的來源。在納入之前，下列何者最應先確認？", "o": ["該批資料的檔案格式是否與本局其他資料完全一致", "本局多數同仁是否普遍認為該資料具有參考價值", "原提供用途與授權範圍是否涵蓋此用途", "該批資料的筆數是否足以讓AI的回答更加流暢"], "a": 3, "e": "他機關提供的資料受原提供目的與約定拘束，納入AI用途前應確認授權範圍，必要時重新徵得同意。"});
BANK.push({"id": "GOV-N117", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.1AI政策與治理指引", "q": "某機關以AI篩選疑似不實的補助申請案，驗證報告顯示「整體準確率98%」，但實際不實案件僅占全部案件約2%。承辦人審閱報告時，最應提出的疑問為何？", "o": ["準確率已高於95%，是否代表系統可以直接上線而不需要再看其他指標", "廠商能否將準確率再提高到100%，並以此作為唯一的驗收門檻", "不實案件的偵測率與誤判率各為多少", "能否改以系統的平均回應速度，作為衡量此系統成效的唯一指標"], "a": 3, "e": "當目標類別比例極低時，模型即使全部判為正常也能有高準確率，須搭配偵測率、誤判率等指標評估。"});
BANK.push({"id": "GOV-N118", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.1AI政策與治理指引", "q": "某機關生成式AI服務上線三個月後，每月雲端運算費用持續大幅增加，遠超原預算。依持續監測與滾動修正的精神，下列處理最適當？", "o": ["分析費用來源，設定配額與告警並調整使用方式", "立即全面停用AI服務，並將費用超支的問題列為機密不對外說明", "不予理會，因為費用增加正代表同仁使用踴躍、推動成效良好", "要求同仁改用個人付費帳號處理公務，以免繼續占用機關預算"], "a": 1, "e": "資源消耗是重要監測指標，應找出成本來源並以配額、告警及架構調整進行滾動修正。"});
BANK.push({"id": "GOV-N119", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.1AI政策與治理指引", "q": "某機關在AI問答服務每則回覆下方設置「這個回答有幫助嗎」及錯誤回報按鈕。此設計最主要的治理目的為何？", "o": ["蒐集使用者回饋，作為持續改善的依據", "統計民眾滿意度後，作為承辦人年終考績的唯一依據", "增加網頁點擊次數，以提高機關網站在搜尋引擎的排名", "讓民眾可以直接修改AI系統的後台設定與回答內容"], "a": 1, "e": "使用者回饋是持續監測的重要來源，可協助發現錯誤並滾動修正服務。"});
BANK.push({"id": "GOV-N120", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.1AI政策與治理指引", "q": "同仁測試機關的AI問答系統時發現，同一個問題詢問多次，得到的答案內容與結論並不一致。此現象主要反映哪一項成效評估面向的問題，應如何處理？", "o": ["資源消耗過低，應增加運算資源以提升答案品質", "資料主權不足，應將伺服器移至國外資料中心", "使用者回饋過多，應關閉回饋功能以減少干擾", "穩定性不足，應重複測試並調整生成參數或檢索設計"], "a": 4, "e": "相同輸入結果不一屬穩定性問題，應透過重複測試、參數調整與檢索優化提升一致性。"});
BANK.push({"id": "GOV-N121", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.1AI政策與治理指引", "q": "某機關規劃以AI協助審查建照申請文件。依導入生命週期治理，在全面上線前，下列哪一種作法最能兼顧效益驗證與風險控管？", "o": ["直接全面上線，再由民眾使用後的抱怨判斷系統是否有問題", "先停止人工審查作業，以確保同仁專心學習使用AI系統", "只要廠商提出書面保證書，即可略過任何試辦或測試程序", "小範圍試辦並與人工審查平行比對"], "a": 4, "e": "試辦與平行作業可在不影響民眾權益下驗證效能、找出問題，是導入中階段的重要控管。"});
BANK.push({"id": "GOV-N122", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.1AI政策與治理指引", "q": "某AI系統已上線兩年，相關法規、業務流程與民眾需求均已有變化。依AI生命週期治理，導入後階段除日常監測外，還應建立何種機制？", "o": ["定期再評估，決定續用、調整、重新訓練或退場", "系統只要沒有發生當機，就可以持續使用而不需要任何檢討", "每年固定更換一次廠商，以確保機關採用的技術永遠最新", "將系統管理權完全移交給廠商，機關從此不再參與相關決策"], "a": 1, "e": "生命週期治理包含定期再評估，依效益與風險決定續用、修正或有計畫地退場。"});
BANK.push({"id": "GOV-N123", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.1AI政策與治理指引", "q": "某機關承辦人參考AI系統的建議，作成駁回民眾申請的處分，事後發現AI建議有誤。關於責任歸屬與救濟，下列敘述何者最正確？", "o": ["AI建議有誤，應由AI系統本身承擔法律責任", "處分出於AI判斷而非人員決定，民眾無法救濟", "責任應全部由提供模型的國外公司承擔，與機關無關", "仍由作成處分的機關負責，民眾得依法提起行政救濟"], "a": 4, "e": "AI僅為輔助工具，對外作成決定的機關仍須負責，民眾的行政救濟權利不因AI參與而受影響。"});
BANK.push({"id": "GOV-N124", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.1AI政策與治理指引", "q": "某機關在高風險AI審核流程中設計「人工覆核」關卡。下列哪一種設計最能確保人類覆核是實質有效的？", "o": ["覆核人員每日須完成數百件確認，系統設計為只需點選同意即可結案", "覆核者具備能力、時間與資訊，並有權推翻AI建議", "覆核畫面只顯示AI的最終結論，不提供判斷依據以免干擾覆核人員", "覆核人員若推翻AI建議須另受懲處，以維持全案處理結果的一致性"], "a": 2, "e": "有效的人類覆核需具備能力、時間、資訊與實際否決權，避免淪為形式上的蓋章。"});
BANK.push({"id": "GOV-N125", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.1AI政策與治理指引", "q": "民眾陳情表示，其申請案遭AI輔助系統判定不符資格，卻不知原因也不知如何申訴。機關檢討時，下列哪一項改善最符合高風險AI的救濟精神？", "o": ["向民眾強調AI判斷經過大量資料訓練十分精準，請其接受結果", "以系統演算法屬廠商智慧財產為由，拒絕說明任何判斷理由", "建議民眾改天重新送件一次，觀察系統結果是否會有所不同", "說明AI參與情形與理由，並提供申訴及人工重審管道"], "a": 4, "e": "受影響者應能獲知AI參與與決定理由，並有申訴與由人員重新審查的管道。"});
BANK.push({"id": "GOV-N126", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.1AI政策與治理指引", "q": "某機關評估導入大型AI模型時，同時將其耗電量、碳排放及對環境的影響納入考量。此作法最能呼應我國《人工智慧基本法》的哪一項基本原則？", "o": ["透明與可解釋", "隱私保護與資料治理", "永續發展與福祉", "公平與不歧視"], "a": 3, "e": "將AI的能源與環境影響納入評估，呼應追求永續發展與社會福祉的原則。"});
BANK.push({"id": "GOV-N127", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.1AI政策與治理指引", "q": "某區公所導入AI語音服務處理民眾臨櫃預約，但同時保留民眾可選擇由承辦人員直接服務的管道，且AI僅提供建議，不代替民眾做決定。此設計最能體現哪一項原則？", "o": ["人類自主", "資安與安全", "永續發展與福祉", "透明與可解釋"], "a": 1, "e": "尊重人的選擇與決定權、讓AI輔助而非取代人的判斷，是人類自主原則的體現。"});
BANK.push({"id": "GOV-N128", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "某機關已導入核准的封閉式地端生成式AI系統，有同仁認為「資料不出機關，所以不必再做任何資安管理」。下列回應何者最正確？", "o": ["地端部署完全沒有資安風險，可開放所有人員不限權限使用", "仍需存取控管、日誌稽核、漏洞修補與監控", "地端部署的系統不會留下任何紀錄，因此不需要辦理稽核", "只要安裝防毒軟體，就能取代其他所有資安管理措施"], "a": 2, "e": "地端部署主要解決資料離開機關的疑慮，內部濫用、權限不當與系統漏洞等風險仍須管理。"});
BANK.push({"id": "GOV-N129", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "某機關自建地端AI系統，對話紀錄完全由機關自行保存。資訊室研擬對話紀錄保存規範時，下列考量何者最適當？", "o": ["為保險起見，所有對話紀錄應永久保存，且全體同仁皆可查閱", "對話紀錄屬於個人隱私，系統應設計為完全不留存任何紀錄", "依稽核與業務需要訂定保存期限及存取權限", "保存期限交由每位使用者依個人習慣自行決定，機關不另規範"], "a": 3, "e": "地端部署時紀錄管理責任回到機關，保存太短不利稽核、太長則增加外洩風險，應明訂期限與權限。"});
BANK.push({"id": "GOV-N130", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "資訊室透過網路流量分析發現，某科室數名同仁長期使用未經核准的外部AI服務處理公文。機關的處理方式下列何者最適當？", "o": ["停止使用並查明輸入過的資料，評估是否通報，並檢討提供合規工具", "既然已經使用很久都沒有出事，可默許其繼續使用以維持行政效率", "立即將相關同仁移送懲處，至於其他後續事項則不需要另外處理", "直接封鎖該服務網址即可，無須了解同仁先前輸入過哪些資料內容"], "a": 1, "e": "處理影子AI應先止血並評估已輸入資料的影響，必要時通報，同時檢討需求以提供核准工具。"});
BANK.push({"id": "GOV-N131", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "機關召開討論未公開政策方向的視訊會議時，一名外部與會者自行開啟某雲端AI會議記錄助理，自動錄音並上傳轉寫。主席最適當的處理為何？", "o": ["AI會議記錄可以提高效率，應鼓勵所有與會者都一起開啟使用", "請其關閉該工具，並重申不得使用未核准AI服務", "只要會後請該AI服務廠商刪除錄音檔，即可確保資料不會外流", "會議尚未作成正式決議，因此討論內容不屬機敏資料，無須處理"], "a": 2, "e": "未經核准的AI記錄工具會將會議內容傳至外部服務，討論未公開政策時應予制止並提醒規範。"});
BANK.push({"id": "GOV-N132", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "承辦人想將「尚未核定發布的新政策草案」貼到外部公開生成式AI服務，請它潤飾成新聞稿。下列判斷何者最正確？", "o": ["可以，只要潤飾後的內容由承辦人再次檢查即可", "不宜，未發布政策草案不應輸入外部AI", "可以，因為政策終究會公開，提前輸入不會有影響", "不宜，但只要改用手機版的AI應用程式就沒有問題"], "a": 2, "e": "未發布政策草案屬負面表列資料，提前輸入外部AI可能造成外洩，即使最終會公開也不例外。"});
BANK.push({"id": "GOV-N133", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "本機關收到他機關函送的機敏資料，承辦人想用外部生成式AI快速整理重點以便簽陳。下列作法何者最適當？", "o": ["不輸入外部AI，依原機關要求及本機關規定處理", "只要刪除發文機關名稱與文號，即可輸入外部AI整理重點", "先詢問外部AI服務是否會保密，若它回答會保密即可使用", "他機關資料不屬本機關管轄，因此不受本機關的使用規範限制"], "a": 1, "e": "他機關機敏資料屬不宜輸入外部AI的資料類型，處理時須同時遵守提供機關的要求。"});
BANK.push({"id": "GOV-N134", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "承辦人將陳情資料中的身分證字號遮蔽後四碼，但保留姓名、住址與陳情內容，便認為已去識別化，可輸入外部AI。下列評論何者最正確？", "o": ["仍可識別特定個人，不構成有效去識別化", "身分證字號已遮蔽，資料即完全不屬於個人資料", "只要遮蔽身分證字號任一部分，即符合去識別化要求", "住址屬於公開資訊，保留與否對識別性沒有任何影響"], "a": 1, "e": "去識別化須確保無法直接或間接識別個人，僅部分遮蔽單一欄位而保留姓名住址，仍可識別當事人。"});
BANK.push({"id": "GOV-N135", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "某機關依ISO/IEC 42001建立AI管理系統，召開年度「管理審查」會議。下列哪一項最適合作為此會議的檢視重點？", "o": ["各AI系統的操作介面配色與字型是否符合多數同仁喜好", "得標廠商業務人員的出勤紀錄、加班時數與差旅費用明細", "僅檢視AI系統當年度的使用人數，其他事項皆不需要討論", "AI政策目標達成、稽核結果、風險處理與改善需求"], "a": 4, "e": "管理審查是管理系統PDCA的一環，由管理階層檢視政策目標、稽核結果與風險處理，以決定改善方向。"});
BANK.push({"id": "GOV-N136", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "某機關的AI案件分類系統原本只供內部參考，現擬擴大為直接通知民眾審查結果，並更換為新版模型。關於風險評估，下列作法何者最適當？", "o": ["原系統上線前已做過風險評估，變更後不必重做", "先行上線使用，待民眾提出投訴後再補做風險評估", "於變更前重新辦理風險評估", "只需由廠商以口頭方式確認新模型沒有問題即可"], "a": 3, "e": "風險評估不是一次性工作，用途擴大或模型更換等重大變更都應在事前重新評估。"});
BANK.push({"id": "GOV-N137", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "資訊室稽核AI系統使用日誌時，發現某帳號連續數晚在深夜大量查詢與其業務無關的民眾資料。下列處理最適當？", "o": ["日誌只是參考用的資料，不需追究此類異常的查詢行為", "保全日誌、暫停權限並依程序調查與通報", "直接刪除該帳號所有的使用日誌紀錄，以避免資料外流", "在機關內部網站公告該帳號持有人的姓名，以達警惕效果"], "a": 2, "e": "日誌稽核的價值在於發現異常後能追查與處置，應保全證據、限制權限並依程序調查與通報。"});
BANK.push({"id": "GOV-N138", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "機關在AI系統導入前辦理「合規性審查」，其主要目的為何？", "o": ["確認系統操作介面是否美觀，並廣受同仁喜愛", "確認廠商報價是否為市場上同類產品的最低價", "確認設計與使用符合相關法令及機關規範", "確認系統能否完全取代人工，以達成員額精簡"], "a": 3, "e": "合規性審查在於事前檢核AI應用是否符合個資、資安、著作權及採購等法令與內部規範，降低日後違法風險。"});
BANK.push({"id": "GOV-N139", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "某機關AI系統上線後，廠商表示將定期自動更新模型版本以提升效能。在契約中針對「模型更新管理」，最應約定下列何者？", "o": ["廠商可依技術需要隨時自行更新，無須另行告知機關", "模型一經驗收即永久禁止任何形式的版本更新與修補", "事前通知並說明變更，經機關測試確認後才上線", "是否更新由每位使用者在操作畫面上自行選擇決定即可"], "a": 3, "e": "模型更新可能改變系統行為與效能，契約應要求事前通知、變更說明與機關測試確認。"});
BANK.push({"id": "GOV-N140", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "機關驗收委外建置的AI文件摘要系統時，下列哪一種驗收方式最為適當？", "o": ["僅觀看廠商事先準備的功能展示影片，即可確認系統功能", "以廠商自行測試並提供的結果報告，作為唯一的驗收依據", "以機關自訂的測試案例與指標實測，並檢視資安檢測", "只要系統能夠正常開機並順利登入，即可視為驗收合格"], "a": 3, "e": "成果驗收應以機關自訂的測試案例及指標實測，並涵蓋資安與交付文件，避免僅依廠商自評。"});
BANK.push({"id": "GOV-N141", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "某AI委外案的廠商駐點工程師需存取機關系統。為確保承商遵守機關規範，下列契約與管理措施何者最完整？", "o": ["工程師屬於廠商員工，機關的資安規範並不適用於其個人行為", "為了方便日常維運作業，可直接提供機關管理者共用帳號密碼", "簽保密切結、最小權限授權、遵守資安規定並於終止時收回權限", "僅需於廠商得標時以口頭方式提醒注意資安即可，不必寫入契約"], "a": 3, "e": "承商人員應受機關資安與保密規範約束，並以最小權限授權，且於離任或契約終止時即時收回。"});
BANK.push({"id": "GOV-N142", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "機關審查AI委外契約時發現，廠商擬將部分功能轉由第三方國外AI服務的應用程式介面（API）處理機關資料。下列處理最適當？", "o": ["此屬廠商內部的技術選擇與架構設計，機關無須過問或審查", "要求事前揭露並經同意，且第三方須受同等資料保護約束", "只要該第三方是國際知名的大型科技公司，即可自動視為安全", "契約中載明由廠商自行負責即可，機關無須確認實際資料流向"], "a": 2, "e": "轉由第三方處理機關資料涉及資料流向與分包風險，應事前揭露、經同意並使其受同等約束，例如不得用於訓練。"});
BANK.push({"id": "GOV-N143", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "某AI委外案即將到期且不再續約，廠商系統中存有機關提供的訓練資料與對話紀錄。契約應事先約定何種處理方式？", "o": ["依約返還或刪除並出具證明", "契約結束後資料即歸廠商所有，可自由運用於其他專案", "資料繼續留在廠商系統中，等下次採購時再拿出來使用", "由廠商依自身需求決定是否刪除，機關無須另行確認"], "a": 1, "e": "契約應明定終止時的資料返還與刪除義務及證明，避免機關資料於契約結束後持續留在廠商端。"});
BANK.push({"id": "GOV-N144", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "承辦人以生成式AI草擬函復民眾的公文，AI在文中引用了一則函釋字號與內容。承辦人送陳前最應做的是什麼？", "o": ["AI已提供明確字號，代表來源可靠，可直接引用", "查證該函釋是否存在、內容是否正確", "只要文句通順即可送陳，引用內容交由長官檢查", "刪除函釋字號但保留內容，以免民眾自行查證"], "a": 2, "e": "生成式AI可能產生看似合理但不存在的內容，承辦人須查證原始資料並負專業判斷之責。"});
BANK.push({"id": "GOV-N145", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "某採購案評選委員為節省時間，打算將各廠商的服務建議書全文上傳至外部生成式AI，並直接採用AI給出的分數作為評分。下列評論何者最正確？", "o": ["可行，AI評分可以排除人情因素，因此會比委員親自評分更加客觀公正", "可行，只要全體評選委員都使用同一個AI服務評分，即可確保結果一致", "不妥，但只要改用付費企業版的AI服務，就可以直接採用其評分結果", "不妥，應由委員親自判斷，且上傳恐違反保密"], "a": 4, "e": "AI產出不得作為決策的唯一依據，評選須由委員親自判斷；廠商建議書亦不宜任意上傳外部服務。"});
BANK.push({"id": "GOV-N146", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "某機關AI客服原先設計要求民眾在對話一開始就輸入身分證字號、出生日期與住址，即使只是詢問開放時間也一樣。依個資保護觀念，下列改善最適當？", "o": ["維持原設計，因為蒐集越多資料越能提升服務品質", "僅在業務確有必要時蒐集最少量個資", "改為要求民眾額外提供工作單位，以便後續統計分析", "將已蒐集到的個資一併用於機關其他業務的活動宣傳"], "a": 2, "e": "個資蒐集應符合特定目的及最小化原則，與服務無關或非必要的個資不應蒐集。"});
BANK.push({"id": "GOV-N147", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "某機關以RAG建置內部AI助理，知識庫同時含一般公告與限閱的人事、密件資料。為避免權限較低的同仁透過提問取得不該看到的內容，下列措施最關鍵？", "o": ["在系統提示詞中加入「請不要洩漏任何機密內容」的指示即可", "將知識庫內所有文件的密等全部調降為一般，以簡化權限管理", "檢索時依使用者權限與文件分級過濾內容", "只要同仁簽署使用同意書，就可以開放存取全部的知識庫內容"], "a": 3, "e": "AI助理不應成為繞過存取控管的管道，須在檢索層依使用者權限與文件分級過濾，僅靠提示詞無法確保安全。"});
BANK.push({"id": "GOV-N148", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "承辦人送出指令後才驚覺，自己誤將含民眾個資的附件上傳到未經核准的外部AI服務。下列處理何者最適當？", "o": ["刪除自己在該服務上的對話紀錄，當作沒有發生過", "先等待一段時間觀察，若沒有民眾反映就不必通報", "請熟悉資訊的朋友幫忙確認該服務是否真的會保存資料", "立即依規定向主管及資安或個資窗口通報"], "a": 4, "e": "發現疑似資料外洩應儘速依程序通報，以利機關評估影響與採取補救，隱匿或自行刪除反而擴大風險。"});
BANK.push({"id": "GOV-N149", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "機關處理AI系統相關資安事件時，下列哪一個流程順序最為合理？", "o": ["發現通報、應變處置、系統復原、檢討改善", "系統復原、檢討改善、發現通報、應變處置", "檢討改善、應變處置、系統復原、發現通報", "應變處置、檢討改善、系統復原、發現通報"], "a": 1, "e": "資安事件處理一般依序為偵測通報、應變控制損害、復原，最後檢討原因並改善防護。"});
BANK.push({"id": "GOV-N150", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "某機關委外建置民眾諮詢用AI客服系統，擬於契約中明定資料處理要求。下列哪一項約定最符合資安與個資管理需求？", "o": ["廠商得於服務期間將機關資料與民眾對話紀錄自由用於優化其商用模型，以持續提升客服回答品質與準確度", "資料存放位置與處理流程屬廠商營業秘密，機關不得要求說明或查核，僅能依廠商定期提供之報告了解運作情形", "明定機關提供之資料與對話紀錄所有權屬機關，廠商不得未經同意用於訓練其他模型，契約終止時並應返還或銷毀", "契約終止後廠商可保留全部資料與對話紀錄備份，以利日後系統維運、問題追查及重新承接時快速銜接"], "a": 3, "e": "AI採購或委外契約應明定資料所有權、使用限制、查核權及終止後的返還或銷毀。常見迷思是把資料處理流程當成廠商營業秘密而放棄查核。"});
BANK.push({"id": "GOV-N151", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "某科員需擬製列為機密等級的函稿，想先請外部雲端生成式AI協助撰寫初稿，再自行修改。依公務使用生成式AI的原則，下列處理何者正確？", "o": ["先將人名與機關名稱刪除後再上傳，即可交由外部AI產生初稿", "機密文書應由承辦人親自撰寫，不得交由外部生成式AI處理", "只要初稿完成後送主管核閱，就可先以外部AI協助撰寫", "使用機關公務電子郵件註冊AI帳號登入，即可處理機密內容"], "a": 2, "e": "機密文書涉及國家機密或機關核心利益，應由承辦人親自撰寫，不得輸入外部生成式AI。遮蔽部分名稱、事後核閱或使用公務帳號，都無法消除資料外洩風險。"});
BANK.push({"id": "GOV-N152", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "承辦人以AI分析一件民眾申請案，AI輸出「建議駁回」並附上理由。依生成式AI使用規範，承辦人接下來最適當的作法為何？", "o": ["AI已綜整全部卷內資料與相關法規，可直接據以擬具駁回函稿並陳核，以免延宕", "為提升效率，只對AI建議駁回的案件抽樣查證，其餘案件則依其建議辦理", "將AI結果僅視為參考，另就事實與法規逐項查證後，本於職權自行判斷", "請AI重新生成一次並比對理由，兩次結論相同即可視為已完成查證並據以辦理"], "a": 3, "e": "AI產出須經查證，且不得作為唯一決策依據，責任仍在承辦人。重複生成結果一致並不代表正確，因為模型可能每次都犯同樣的錯。"});
BANK.push({"id": "GOV-N153", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "某機關AI平台發現一名短期實習生帳號被授予管理員權限，可匯出全部使用紀錄。下列何者是最適當的改善方向？", "o": ["改由全體同仁共用一組管理帳號，需要時輪流使用，以便人員異動時不必調整權限", "一次開放較大權限以利作業彈性，並請使用者簽署切結書，由其自律不得濫用即可", "依最小權限原則按職務授權，並定期審視權限、於人員異動時即時調整或停用帳號", "維持現有權限配置，僅於年度稽核時一併檢視帳號清單，平時不予更動以免影響作業"], "a": 3, "e": "存取控管應落實最小權限、角色分工與異動時即時調整，並搭配日誌稽核。共用帳號會使操作無法歸責，而延後檢視則使權限長期過大。"});
BANK.push({"id": "GOV-N154", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "某機關對外AI問答服務的監控發現，同一外部來源在短時間內送出大量經系統化設計的查詢，疑似蒐集輸出以重建近似模型。此行為最可能屬於下列何種威脅？", "o": ["資料投毒，於訓練資料中植入錯誤樣本以扭曲模型的判斷結果", "越獄攻擊，以大量提示詞繞過安全限制使模型輸出違規內容", "阻斷服務攻擊，以大量請求耗盡系統資源使服務中斷無法使用", "模型竊取（模型萃取），以大量查詢與回應複製模型行為"], "a": 4, "e": "模型竊取是以大量查詢蒐集輸入輸出對，進而複製模型。對策包括限制查詢頻率、監控異常行為與保留日誌，不應與資料投毒（針對訓練資料）混淆。"});
BANK.push({"id": "GOV-N155", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "機關訂定生成式AI使用規範時採「負面表列」，列舉禁止輸入的資料類型。下列關於其管理的敘述何者最適當？", "o": ["公布後即應維持不變，以確保規範穩定與同仁遵循一致，不宜隨意調整修正", "未列於負面清單內的資料即可自由輸入，不再受個資及保密相關規定拘束", "清單只需列出公文系統內的資料類型，個資與業務機敏資料由同仁自行判斷", "應隨法規修正、資安事件與技術發展定期檢討更新，並向同仁宣導"], "a": 4, "e": "負面表列需配合環境變化定期檢討，並涵蓋個資、機敏與機密等類型。未列入清單不代表可任意輸入，仍須遵守個資法與保密規定。"});
BANK.push({"id": "GOV-N156", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "承辦人將陳情信中陳情人姓名刪除後上傳外部AI分析，但保留了完整住址門牌、職業及特殊事由。下列分析何者最正確？", "o": ["僅刪除姓名未必已去識別化，若剩餘資訊組合仍可間接識別特定人，仍屬個資，須依規範處理", "姓名已經遮蔽，其餘住址、職業等資訊無法單獨指向特定人，因此均不屬個資，可直接上傳分析", "住址門牌屬於可公開查得的資訊，不受個人資料保護規範，可自由輸入外部AI進行分析", "已刪除姓名即屬去識別化資料，後續保管由AI平台業者負責，機關無須再評估外洩風險"], "a": 1, "e": "個資包含可直接或間接識別特定人之資料，多項資訊組合仍可能識別身分。去識別化須評估重新識別風險，不能只刪姓名。"});
BANK.push({"id": "GOV-N157", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "某機關欲上線對外民眾使用的AI聊天機器人，下列哪一項防護設計最能降低其遭濫用或資料外洩的風險？", "o": ["為使回答更完整正確，賦予機器人機關內部資料庫的完整讀取權限，並可即時查詢", "設定輸入與輸出內容過濾、限制可存取資料範圍與呼叫頻率，並保留操作日誌供稽核", "採用知名大型模型，信賴其內建安全機制自行判斷內容是否適當，不另設防護機制", "為避免留存個資衍生疑慮，上線後不保存任何系統日誌，對話內容亦即時刪除不留紀錄"], "a": 2, "e": "對外服務應採多層防護：輸入輸出過濾、權限與資料範圍限縮、頻率限制及日誌稽核。過度授權與不留日誌，都會增加風險並使事件無法追查。"});
BANK.push({"id": "GOV-N158", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "機關在AI系統上線前辦理「紅隊演練（Red Teaming）」，其主要目的為何？", "o": ["在一般使用情境下測試模型回答的流暢度、正確率與回應速度，確認符合驗收標準", "以使用者滿意度問卷與試用意見取代資安測試，縮短上線前的準備與驗證時間", "模擬攻擊者使用提示詞注入、越獄等手法測試系統，預先發現弱點並修補", "由紅隊逐項核對供應商提供的合規文件與授權證明是否齊全，以完成採購驗收"], "a": 3, "e": "紅隊演練是以攻擊者視角主動測試AI系統的安全弱點。流暢度、問卷與文件審查有其用途，但無法取代對抗式測試。"});
BANK.push({"id": "GOV-N159", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.2AI法規與資安風險管理", "q": "某機關建置內部知識庫問答系統（檢索增強生成），將各科室文件全數建立索引後，一般同仁竟能透過提問取得人事考核等限閱文件的內容。最根本的改善作法為何？", "o": ["在系統提示詞中加註「請勿透露人事等機敏資料」，即可完全防止限閱內容外洩", "屬內部系統且使用者皆為機關同仁，所有人皆可視為有權閱覽，不需另行限制", "檢索階段沿用原文件存取權限，依提問者身分過濾可被檢索的內容", "調高模型的隨機性參數，降低機敏內容被完整輸出的機率，以兼顧便利與保密"], "a": 3, "e": "RAG系統須在檢索層落實文件層級的存取控管，不能只靠提示詞要求模型自制。提示詞限制可被繞過，不能取代權限機制。"});
BANK.push({"id": "GOV-N160", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.3AI應用下的倫理準則與智慧財產實務", "q": "承辦人依AI系統的排序結果核定某項補助，事後民眾申訴審核有誤。關於責任歸屬，下列何者正確？", "o": ["排序結果由AI系統產生，應由系統供應商承擔全部行政責任，機關與承辦人無須負責", "核定屬權責人員職權，機關與承辦人須對決定負責，不得以AI建議為由卸責", "因核定係依系統自動判斷結果辦理，承辦人已盡注意義務，可主張個人完全免責", "民眾申請時已知悉機關採用AI審核，應自行承擔系統誤差所生的風險與不利結果"], "a": 2, "e": "AI僅為輔助工具，行政處分與業務決策的最終問責仍在權責人員及機關。把責任推給系統或廠商，不符合行政倫理。"});
BANK.push({"id": "GOV-N161", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.3AI應用下的倫理準則與智慧財產實務", "q": "某機關以歷史稽查資料訓練AI風險模型，用來挑選抽查對象，發現過去資料多集中於特定行政區的店家。下列何者最能降低不公平風險？", "o": ["歷史稽查資料即為客觀發生的事實紀錄，以其訓練的模型結果毋須另行檢驗是否公平", "只要模型在測試資料上的整體準確率夠高，即可證明對各行政區店家沒有歧視或偏差", "檢視訓練資料代表性，並依地區、族群等分組檢測結果差異，必要時調整模型並保留人工複核", "將行政區與地址欄位自訓練資料中刪除後，其他欄位即不再隱含地區資訊，可完全排除地區偏誤的影響"], "a": 3, "e": "歷史資料可能反映過去的抽查偏向，需做公平性檢測。即使隱藏敏感欄位，其他變數仍可能成為替代指標，因此不能視為已完全排除偏誤。"});
BANK.push({"id": "GOV-N162", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.3AI應用下的倫理準則與智慧財產實務", "q": "某局處規劃以AI取代部分臨櫃申辦，導入前依社會影響檢核的精神，下列何者最為適當？", "o": ["只要試辦期間整體滿意度平均值達標，即可全面上線並同步裁撤臨櫃申辦服務", "以系統建置成本、處理效率與節省人力為主要評估項目，其他影響留待上線後再議", "事前評估對高齡者、身心障礙者及數位弱勢族群的影響，並保留人工與替代服務管道", "先行全面上線以累積使用數據，待民眾大量反映問題後再依意見逐步調整改善"], "a": 3, "e": "社會影響檢核重視弱勢與受影響族群的近用性，避免數位落差造成不公平。只看平均值或效率，會忽略少數群體的需求。"});
BANK.push({"id": "GOV-N163", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.3AI應用下的倫理準則與智慧財產實務", "q": "AI協助草擬的新聞稿中出現「視頻」「軟件」「信息」等用語，承辦人發布前應如何處理？", "o": ["AI輸出係依大量中文語料訓練而成，所用詞彙即為標準用語，無須另行修改", "兩岸用語皆屬中文且意思相通，不影響對外溝通與理解，可直接發布以爭取時效", "只要以轉換工具將全文的簡體字轉成繁體字，即可完成用語在地化調整", "依我國慣用語與機關用語規範校正，例如改為「影片」「軟體」「資訊」"], "a": 4, "e": "生成內容需符合在地語境與政策語彙，避免用語誤植。僅轉換字體無法解決詞彙差異，仍須人工校對。"});
BANK.push({"id": "GOV-N164", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.3AI應用下的倫理準則與智慧財產實務", "q": "某機關的政策文宣初稿中，AI將我國原住民族稱為「少數民族」或「山地同胞」。下列處理何者最適當？", "o": ["保留AI所用稱謂，因其較為通俗易懂，有助於一般民眾快速理解文宣內容", "統一改稱「少數族群」，以涵蓋各類群體並避免逐一列舉各族名稱的困擾", "請AI再生成多個版本後自行選定最適當的稱呼，不需另經人工審視確認", "依我國法制與官方慣用語改以「原住民族」稱之，並尊重各族自身稱謂"], "a": 4, "e": "生成內容須符合我國法制與政策語彙，避免價值表述或稱謂不當。AI可能沿用不符本地脈絡的詞彙，須由承辦人把關。"});
BANK.push({"id": "GOV-N165", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.3AI應用下的倫理準則與智慧財產實務", "q": "AI協助草擬的函稿內文與日期皆使用西元年份，承辦人依公文書寫慣例，下列處理何者正確？", "o": ["兩種紀年皆屬有效表示方式，維持AI草稿的西元年份即可陳核", "為與國際接軌並便於系統處理，公文日期應一律改採西元紀年", "AI草擬時已依公文範本自動檢查格式，不必再逐一人工檢視", "公文日期依規定採民國紀年，應將AI草稿修正後再陳核"], "a": 4, "e": "我國公文書的日期以民國紀年為準。AI草稿常不熟悉這類格式慣例，承辦人仍須逐項校對。"});
BANK.push({"id": "GOV-N166", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.3AI應用下的倫理準則與智慧財產實務", "q": "某機關上線AI線上客服，下列哪項設計最符合維護人類自主的精神？", "o": ["讓民眾可隨時轉接真人服務或使用其他申辦管道，不強迫只能與AI互動", "為節省人力並提升效率，全面關閉人工服務窗口，統一由AI客服處理", "僅在AI自行判斷民眾確有需要時，才由系統主動轉接真人客服處理", "人工客服管道僅保留給機關內部同仁使用，民眾一律透過AI客服洽詢"], "a": 1, "e": "人類自主要求民眾保有選擇權，包括尋求人工協助的管道。完全依賴AI或由系統單方決定是否轉接，會削弱民眾的自主權。"});
BANK.push({"id": "GOV-N167", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.3AI應用下的倫理準則與智慧財產實務", "q": "民眾詢問為何補助申請遭否准，承辦人答覆「系統算出來就是這樣」。下列評論何者最正確？", "o": ["機關應能說明決定所依據的事實、法規與理由，不得僅以AI運算結果搪塞", "AI模型與演算法屬廠商營業秘密，機關一律不得向民眾說明否准的具體理由", "只要AI系統經驗證準確率高，機關即無另行向民眾說明決定理由的義務", "以「經系統判定不符資格」作為處分理由，即已符合行政程序的說明要求"], "a": 1, "e": "透明與可解釋性要求機關能對民眾說明決定理由，且決定責任屬機關。引用系統判定而不說明事實與法規依據，並不足夠。"});
BANK.push({"id": "GOV-N168", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.3AI應用下的倫理準則與智慧財產實務", "q": "某主管每日需簽核數百件AI預審結果，實務上一律核可，僅在簽核欄位簽章。關於有效的人類監督，下列敘述何者最正確？", "o": ["只要流程上設有主管簽章欄位並完成核章，即已符合有效人類監督的要求", "覆核人員愈少愈能維持與AI結果的一致性，因此應集中由單一主管簽核", "改以AI自動簽核取代人工覆核，可提升效率並確保監督品質維持一致", "有效監督需具備足夠時間、資訊與權限來質疑AI結果，避免流於形式覆核"], "a": 4, "e": "形式化的覆核無法發揮監督功能，也是自動化偏誤的表現。真正的監督須讓覆核者有能力、時間與授權去推翻AI建議。"});
BANK.push({"id": "GOV-N169", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.3AI應用下的倫理準則與智慧財產實務", "q": "某機關建置AI服務前規劃蒐集民眾資料，依隱私保護與資料治理精神，下列何者最適當？", "o": ["先廣泛蒐集各類欄位資料，以備日後模型訓練之需", "僅蒐集達成目的所必要的資料，並明確告知使用目的", "只要民眾未明示反對，即可蒐集其所有相關欄位", "資料越多越能消除偏誤，因此應盡量擴大蒐集範圍"], "a": 2, "e": "資料最小化與目的限定是隱私保護的基本原則。蒐集範圍超出必要，反而增加風險，也不會自動消除偏誤。"});
BANK.push({"id": "GOV-N170", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.3AI應用下的倫理準則與智慧財產實務", "q": "某機關要求AI系統具備備援機制、抵禦惡意輸入，並在發生錯誤時能安全降級運作。依歐盟《可信賴AI倫理準則》七大要素，這主要對應下列何者？", "o": ["技術穩健與安全", "人類能動性與監督", "透明", "多元、不歧視與公平"], "a": 1, "e": "備援、抗攻擊與安全降級屬技術穩健與安全的要求。人類能動性與監督談的是人的決定權與介入能力，透明則談可追溯與可解釋。"});
BANK.push({"id": "GOV-N171", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.3AI應用下的倫理準則與智慧財產實務", "q": "同仁僅向圖像生成工具輸入文字提示詞並反覆調整二十次後取得滿意的圖片，關於其著作權，依美國著作權局的立場，下列何者較為正確？", "o": ["投入的時間與反覆調整的次數越多，即可認定具創作控制而取得完整著作權", "單憑輸入與調整提示詞，通常尚不足以認定其對輸出圖像具有足夠的創作控制", "提示詞寫得越長越詳細，輸出圖像即屬提示者的著作而當然受到保護", "只要發布時未標示為AI生成，即視為人類創作而受著作權完整保護"], "a": 2, "e": "美國著作權局認為提示詞對輸出的控制不足，不能僅憑提示即成為作者。投入時間或隱瞞AI使用，都不能創造著作權。"});
BANK.push({"id": "GOV-N172", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.3AI應用下的倫理準則與智慧財產實務", "q": "同仁先手繪草圖，再請AI依草圖精修並上色。關於著作權保護，下列敘述何者較為合理？", "o": ["整張成品因源自同仁手繪草圖，AI精修與上色部分也全部屬人類著作", "人類手繪草圖若具原創性本身受保護，但AI生成的成分則難以主張受保護", "草圖一旦輸入AI工具進行加工，原草圖即喪失其全部著作權保護", "使用AI加工後，草圖與成品皆成為公共財，任何人皆可自由利用"], "a": 2, "e": "保護範圍取決於人類實質創作投入的部分，AI獨立生成的部分一般難以主張著作權。輸入AI並不會使原有著作權消滅。"});
BANK.push({"id": "GOV-N173", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.3AI應用下的倫理準則與智慧財產實務", "q": "機關取得一張採「創用CC姓名標示—禁止改作（CC BY-ND）」授權的圖片，想先用AI轉換成水彩風格後再於宣導品發布。下列何者正確？", "o": ["禁止改作條款不允許散布改作後的版本，應使用原圖或另取得授權", "只要明確標示原作者姓名與授權條款，即可自由改作後對外發布", "禁止改作條款僅限制商業使用，機關宣導屬非營利用途，故可改作", "AI轉換風格屬機器自動處理而非人為改作，因此不受禁止改作條款限制"], "a": 1, "e": "ND代表可在標示姓名下散布原作，但不得散布改作版本。以AI轉換風格仍可能構成改作，與是否商業使用無關。"});
BANK.push({"id": "GOV-N174", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.3AI應用下的倫理準則與智慧財產實務", "q": "機關取得一張採「創用CC姓名標示—相同方式分享（CC BY-SA）」授權的插圖，並據以製作衍生作品對外發布。下列何者最符合授權條件？", "o": ["只需標示原作者，衍生作品可改採任何限制性授權", "標示原作者及授權，並以相同授權條款釋出衍生作品", "衍生作品須一律改採CC0釋出，放棄全部著作權", "此類授權僅在商業使用時才要求以相同方式分享"], "a": 2, "e": "BY-SA除標示姓名外，要求衍生作品以相同或相容條款分享。常見迷思是以為只要標示作者即可自行改用其他授權。"});
BANK.push({"id": "GOV-N175", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.3AI應用下的倫理準則與智慧財產實務", "q": "機關使用一張標示為CC0的照片製作文宣，下列敘述何者最適當？", "o": ["CC0代表圖中所有內容，包括人物肖像與商標，均已放棄權利而可任意使用", "CC0雖可免費使用，但每次使用前仍須逐次取得權利人書面同意才合法", "CC0表示權利人放棄著作權主張，但圖中人物肖像或商標等其他權利仍須另行確認", "CC0僅限個人學習與研究使用，不得用於政府文宣等公開宣導用途"], "a": 3, "e": "CC0針對著作權部分，不處理肖像、人格權、商標等第三方權利。發布前仍需檢核這些其他權利。"});
BANK.push({"id": "GOV-N176", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.3AI應用下的倫理準則與智慧財產實務", "q": "承辦人在簡報中引用新聞媒體的一段報導文字，下列作法何者較符合合理使用的原則？", "o": ["公開在網路上的資料，皆可整篇轉載", "引用他人文字不須註明出處，以免簡報版面雜亂", "於說明所需的合理範圍內引用，並明示出處", "機關屬公部門，一律不受著作權限制"], "a": 3, "e": "合理使用強調必要範圍內的引用，且通常須明示出處。資料公開並不代表可任意整篇轉載。"});
BANK.push({"id": "GOV-N177", "subj": "GOV", "src": "追加 2026-11-09 新題", "official": false, "topic": "2.AI政策法制／2.3AI應用下的倫理準則與智慧財產實務", "q": "同仁請AI「仿某位在世畫家的風格」生成宣導插畫。關於著作權風險，下列敘述何者最正確？", "o": ["畫風屬畫家獨特的創作成果，受著作權保護，任何仿其風格的作品皆構成侵權", "由AI生成的作品並非人類直接繪製，因此不可能侵害他人的著作權", "只要在作品上註明「仿某畫家風格」，即視為已取得授權而可公開使用", "風格本身屬概念，非著作權保護標的，但若輸出重現該畫家的具體表達，仍可能侵權"], "a": 4, "e": "著作權保護表達而非思想或風格，但輸出若與特定作品相同或實質近似，仍有侵權疑慮。AI生成不構成免責理由，註明仿作也不等於授權。"});
